from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0]); bg=max(set(v for row in grid for v in row), key=lambda v:sum(row.count(v) for row in grid))
    seen=set(); out=[r[:] for r in grid]
    for i in range(h):
      for j in range(w):
        c=grid[i][j]
        if c==bg or (i,j) in seen: continue
        q=[(i,j)]; seen.add((i,j)); comp=[]
        while q:
          r,k=q.pop(); comp.append((r,k))
          for nr,nk in ((r-1,k),(r+1,k),(r,k-1),(r,k+1)):
            if 0<=nr<h and 0<=nk<w and (nr,nk) not in seen and grid[nr][nk]==c:
              seen.add((nr,nk)); q.append((nr,nk))
        if len(comp)==1:
          r,k=comp[0]
          neighbors=[grid[nr][nk] for nr,nk in ((r-1,k),(r+1,k),(r,k-1),(r,k+1)) if 0<=nr<h and 0<=nk<w and grid[nr][nk]!=c]
          counts={v:neighbors.count(v) for v in neighbors}
          out[r][k]=max(counts,key=counts.get) if counts else bg
    return out

